SOURCES = {
 'backend': ['python-docs', 'postgres-transactions'],
 'frontend': ['mdn-fetch', 'w3c-dialog-pattern'],
 'qa': ['owasp-authorization'],
 'devops': ['k8s-deploy'],
 'ml': ['sklearn-metrics', 'sklearn-pitfalls'],
 'security': ['owasp-authorization', 'owasp-ssrf'],
}

def operations(spec, grade, rng: random.Random):
    result = []
    for competency, rows in BANK[spec].items():
        prompt, correct, *rest = rows[GRADES.index(grade)]
        wrong, reason = rest[:3], rest[3]
        assert len(set([correct] + wrong)) == 4
        options = [(True, correct)] + [(False, value) for value in wrong]
        rng.shuffle(options)
        choices, expected = [], None
        for valid, text in options:
            identity = secrets.token_hex(5)
            choices.append({'id': identity, 'text': text})
            if valid:
                expected = identity
        result.append({'id': 'item_' + secrets.token_hex(8), 'kind': 'choice',
                       'competency': competency, 'family': f'{spec}:{competency}:grade_decision',
                       'version': VERSION, 'prompt': prompt, 'choices': choices,
                       'source_ids': SOURCES[spec], 'difficulty_scope': f'Authored {grade} constraints; not an empirically calibrated difficulty.',
                       'private': {'expected': expected, 'rationale': reason}})
    return result
